INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  1956,
  'S',
  '3602008',
  'Servicio de apoyo a la implementación de políticas públicas en el marco del trabajo decente',
  'Estas políticas comprenden una amplia gama de instrumentos que pretenden incidir directamente sobre la estructura y el funcionamiento del mercado de trabajo en el sentido de favorecer la empleabilidad y los ingresos de sus participantes y por tanto no se limitan a responder por la mitigación de los efectos del desempleo, sino que combinan distintos instrumentos que de forma complementaria se proponen aumentar el empleo, mejorar la calidad del trabajo y su productividad, elevar los ingresos laborales, defender el empleo existente, mejorar tanto la calidad de la fuerza de trabajo como el funcionamiento del mercado laboral y apoyar a los ocupados en riesgo de desocupación, así como agilizar el encuentro de la oferta y demanda laboral. ',
