INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  2329,
  'S',
  '4003036',
  'Servicio asistencia técnica en el monitoreo a los recursos Sistema General de Participaciones SGP - Agua Potable y Saneamiento Básico',
  'Corresponde al acompañamiento que se realiza a las Entidades Territoriales, para promover el uso adecuado de los recursos del Sistema General de Participaciones-SGP-APSB. Para este propósito, se realizan diferentes tipos de acompañamiento tales como la realización de eventos regionales, capacitaciones, atención telefónica, asistencia virtual y atención personalizada.',
