  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');
INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  2746,
  'S',
  '4401010',
  'Servicios de promoción en temáticas de la Jurisdicción Especial de la Paz',
  'Involucra todas las actividades de difusión, divulgación y posicionamiento (circulación) de las herramientas y contenidos de la Jurisdicción Especial para la Paz, teniendo en cuenta los grupos poblacionales a los que atiende la entidad. Además, los servicios de promoción incluirán también las actividades ligadas al diseño, producción y elaboración de  piezas y estrategias comunicativas que serán utilizadas, posteriormente, para la circulación de los contenidos de la Jurisdicción Especial para la Paz en diversos medios, plataformas y canales de participación. ',
