INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  2748,
  'S',
  '4401015',
  'Servicio de apoyo en protección colectiva',
  'Consiste en la valoración de riesgo, definición e implementación de medidas de protección colectiva, de acuerdo al proyecto de Ley Estatutaria 08 de 2017, Art. 17, "De oficio o a solicitud de parte, por cuenta propia o a través del representante en la Jurisdicción Especial para la Paz se adoptarán medidas adecuadas y necesarias, conforme lo establezca la Ley procedimental, para proteger los derechos de los procesados, las víctimas, testigos e intervinientes que ante ella concurran, los cuales podrán ser vinculados a los programas de Protección de la Unidad Nacional de Protección con debido respeto de las garantías procesales, cuando sus derechos fundamentales a la vida y seguridad personal se encuentren amenazados por su participación en el proceso antes la Jurisdicción Especial para la Paz."',
