-- SPD_MONITORING_RECORD (0 registros)

-- Rehabilitar FK y reiniciar IDENTITY / secuencias ---------------------------
ALTER TABLE ENTIDADES_PRY       ENABLE CONSTRAINT ENT_PRY_SPD_PADRE_FK;
ALTER TABLE SPD_PRODUCT_CATALOG ENABLE CONSTRAINT SPD_PROD_CAT_PARENT_FK;
ALTER TABLE SPD_DEV_PLAN_LEVEL  ENABLE CONSTRAINT SPD_DPL_PARENT_FK;
ALTER TABLE SPD_GOAL            ENABLE CONSTRAINT SPD_GOAL_PARENT_FK;

BEGIN
  FOR t IN (SELECT table_name FROM user_tab_identity_cols WHERE table_name LIKE 'SPD\_%' ESCAPE '\') LOOP
    EXECUTE IMMEDIATE 'ALTER TABLE ' || t.table_name ||
      ' MODIFY ID GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH LIMIT VALUE)';
  END LOOP;
END;
/

DECLARE
  PROCEDURE restart_seq(p_seq VARCHAR2, p_sql VARCHAR2) IS
    v_max NUMBER;
  BEGIN
    EXECUTE IMMEDIATE p_sql INTO v_max;
    EXECUTE IMMEDIATE 'ALTER SEQUENCE ' || p_seq || ' RESTART START WITH ' || (NVL(v_max, 0) + 1);
  END;
BEGIN
  restart_seq('SEQ_ENTIDADES_PRY',   'SELECT MAX(ID) FROM ENTIDADES_PRY');
  restart_seq('SEQ_ESTRUCTURA_PLAN', 'SELECT MAX(ID) FROM PLAN_DESARROLLO');
  restart_seq('SEQ_USUARIOS',        'SELECT MAX(ID) FROM USUARIOS');
END;
/

COMMIT;

-- Las vistas quedan inválidas tras los ALTER TABLE anteriores; se recompilan
BEGIN
  DBMS_UTILITY.COMPILE_SCHEMA(schema => USER, compile_all => FALSE);
END;
/
SET FEEDBACK ON

